import type { CSSProperties } from 'react'

import { cx } from '~/lib/cx'
import styles from './spinner.module.scss'

export type SpinnerSize = 'sm' | 'md' | 'lg' | 'xl'

const SIZE: Record<SpinnerSize, string> = {
  sm: styles.sm,
  md: '',
  lg: styles.lg,
  xl: styles.xl,
}

export interface SpinnerProps {
  size?: SpinnerSize
  /** Announced to assistive tech. Pass `null` when a visible label exists. */
  label?: string | null
  /** Use on filled primary surfaces. */
  onPrimary?: boolean
  /** Pixel override for one-off cases. */
  pixels?: number
  className?: string
}

export function Spinner({
  size = 'md',
  label = 'Loading',
  onPrimary = false,
  pixels,
  className,
}: SpinnerProps) {
  return (
    <span
      role={label ? 'status' : undefined}
      aria-label={label ?? undefined}
      aria-hidden={label ? undefined : true}
      className={cx(
        styles.root,
        SIZE[size],
        onPrimary && styles.onPrimary,
        className,
      )}
      style={
        pixels
          ? ({ '--spinner-size': `${pixels}px` } as CSSProperties)
          : undefined
      }
    />
  )
}

@use 'styles' as vz;

.root {
  --spinner-size: 1.125rem;
  --spinner-width: 2px;

  display: inline-block;
  flex: none;
  width: var(--spinner-size);
  height: var(--spinner-size);
  border: var(--spinner-width) solid vz.color('foreground', 0.14);
  border-top-color: vz.color('primary');
  border-radius: vz.radius('full');
  animation: vz-spin 0.7s linear infinite;

  @include vz.motion-reduce {
    animation-duration: 2.4s;
  }
}

.sm {
  --spinner-size: 0.875rem;
}

.lg {
  --spinner-size: 1.5rem;
  --spinner-width: 2.5px;
}

.xl {
  --spinner-size: 2rem;
  --spinner-width: 3px;
}

.on-primary {
  border-color: vz.color('primary-foreground', 0.3);
  border-top-color: vz.color('primary-foreground');
}

@keyframes vz-spin {
  to {
    transform: rotate(360deg);
  }
}
